MAP
    NAME "SS_MAP_INFO_CUENTAS_DERECHOS"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
            'wfs_title' 'Derechos'
            'wfs_enable_request' '*'
            'wfs_getfeature_formatlist' 'gml,geojson'
            'gml_featureid' 'id_cuenta_derechos'
            'gml_include_items' 'all'
        END #METADATA
    END #WEB   
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_cuentas_derechos.log"
    DEBUG 0  
    LAYER
        NAME "SS_MAP_INFO_CUENTAS_DERECHOS"
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        METADATA
            'gml_include_items' 'all'     
        END #METADATA
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        DATA "gm_cuenta_derechos from l_cuenta_derechos using unique id_cuenta_derechos using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        LABELCACHE ON
        LABELITEM "nb_fraccionamiento"
        CLASS
            NAME "Nombre Fraccionamiento"
            LABEL	
                TYPE TRUETYPE
                FONT 'ARIAL'
                SIZE 19
                PARTIALS FALSE
                COLOR 000 000 000
            END	#LABEL
            STYLE
                WIDTH 8
                COLOR 246 239 090
                OUTLINECOLOR 000 000 000
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP